import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.Mock;
import org.mockito.junit.MockitoJUnitRunner;

import java.util.List;
import java.util.Map;
import java.util.Optional;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import static org.mockito.ArgumentMatchers.anyString;
import static org.mockito.Mockito.when;

@RunWith(MockitoJUnitRunner.class)
public class CommentsConfigurationTest {

    @Mock
    private Map<String, List<String>> commentsMap;

    @Mock
    private String path;

    @Mock
    private String commentLine;

    private CommentsConfiguration commentsConfiguration = new CommentsConfiguration();

    @Test
    public void newCommentConfigurationIsEmpty() {
        assertEquals(0, commentsConfiguration.getAllComments().size());
    }

    @Test
    public void newCommentConfigurationFromMapIsNotEmpty() {
        when(commentsMap.get(anyString())).thenReturn(List.of(commentLine));
        Map<String, List<String>> commentMap = Map.of(path, List.of(commentLine));
        CommentsConfiguration configuration = new CommentsConfiguration(commentMap);
        assertEquals(1, configuration.getAllComments().size());
    }

    @Test
    public void setCommentOverwritesExistingComment() {
        when(commentsMap.get(anyString())).thenReturn(List.of("old comment"));
        Map<String, List<String>> commentMap = Map.of(path, List.of("new comment"));
        CommentsConfiguration configuration = new CommentsConfiguration(commentMap);
        configuration.setComment(path, "new comment");
        assertEquals(1, configuration.getAllComments().get(path).size());
    }

    @Test
    public void setCommentAddsNewLineAsEmptyLine() {
        Map<String, List<String>> commentMap = Map.of(path, List.of(""));
        CommentsConfiguration configuration = new CommentsConfiguration(commentMap);
        configuration.setComment(path, commentLine);
        assertEquals(0, configuration.getAllComments().get(path).size());
    }

    @Test
    public void setCommentSetsLinesWithMarker() {
        when(commentsMap.get(anyString())).thenReturn(List.of());
        Map<String, List<String>> commentMap = Map.of(path, List.of(commentLine));
        CommentsConfiguration configuration = new CommentsConfiguration(commentMap);
        configuration.setComment(path, commentLine + ": " + commentLine);
        assertEquals(2, configuration.getAllComments().get(path).size());
    }

    @Test
    public void getAllCommentsReturnsUnmodifiableView() {
        when(commentsMap.get(anyString())).thenReturn(List.of(commentLine));
        Map<String, List<String>> commentMap = Map.of(path, List.of(commentLine));
        CommentsConfiguration configuration = new CommentsConfiguration(commentMap);
        assertEquals(1, configuration.getAllComments().size());
        assertTrue(configuration.getAllComments().containsKey(path));
    }

    @Test
    public void getAllCommentsReturnsEmptyForNonExistingPath() {
        when(commentsMap.get(anyString())).thenReturn(List.of("old comment"));
        Map<String, List<String>> commentMap = Map.of();
        CommentsConfiguration configuration = new CommentsConfiguration(commentMap);
        assertEquals(0, configuration.getAllComments().size());
        assertTrue(configuration.getAllComments().containsKey(path));
    }

    @Test
    public void setCommentSetsLinesWithMultipleMarkers() {
        when(commentsMap.get(anyString())).thenReturn(List.of());
        Map<String, List<String>> commentMap = Map.of(path, List.of(commentLine));
        CommentsConfiguration configuration = new CommentsConfiguration(commentMap);
        configuration.setComment(path, "comment line 1" + ": " + commentLine + "; " + commentLine + ": " + commentLine);
        assertEquals(3, configuration.getAllComments().get(path).size());
    }

    @Test
    public void setCommentSetsLinesWithNoMarker() {
        when(commentsMap.get(anyString())).thenReturn(List.of());
        Map<String, List<String>> commentMap = Map.of(path, List.of(commentLine));
        CommentsConfiguration configuration = new CommentsConfiguration(commentMap);
        configuration.setComment(path, "comment line without marker");
        assertEquals(1, configuration.getAllComments().get(path).size());
    }

    @Test
    public void setCommentSetsLinesWithMultipleNewLines() {
        when(commentsMap.get(anyString())).thenReturn(List.of());
        Map<String, List<String>> commentMap = Map.of(path, List.of(commentLine));
        CommentsConfiguration configuration = new CommentsConfiguration(commentMap);
        configuration.setComment(path, "\n" + "comment line with multiple new lines" + "\n");
        assertEquals(2, configuration.getAllComments().get(path).size());
    }
}
